It is a folk theorem that the composition
 \begin{equation*}
  S \xrightarrow{[X]} K(\Sigma^\infty_+ \Omega X) \xrightarrow{\mathrm{tr}} \thh (\Sigma^\infty_+ \Omega X) \simeq \Sigma^\infty_+ \mc{L} X \to S 
  \end{equation*} 
is the Euler characteristic.

The most illuminating examples of bicategories for this paper are: 

\begin{itemize}
  \item The bicategory whose 0-cells are rings and, for rings $A$ and $B$, $\mc{B}(A,B)$ is the category of $(A,B)$-bimodules.  The horizontal composition is the tensor product.
  \item The bicategory whose 0-cells are spaces and, for spaces $A$ and $B$, $\mc{B}(A,B)$ is the category of spaces over $A\times B$.  The  horizontal composition is the pullback 
along the diagonal.  This bicategory also has a stable version \cite{maysig:pht}.
\end{itemize}

Note that   if $\shvar{}{-}$ is a shadow functor on $\mc{B}$, then the composite
  \[\xymatrix{
    \shvar{}{M\odot N} \ar[r]^\theta &
    \shvar{}{N\odot M} \ar[r]^\theta &
    \shvar{}{M\odot N}
   }\]
  is the identity \cite[Prop.~4.3]{ps:bicat}.

For objects $a$ and $a'$ in $\mc{A}$, a choice for the   
coevaluation is
\begin{align*}
 {\sA}(a,a')\xrightarrow{F} \sC(F(a),F(a'))&\cong \sC(F(a),F(a'))\otimes 1_{\sV}
 \\
 &\to \sC(F(a),F(a'))\otimes\sC(F(a'),F(a'))\to \sC(F(a),-)\odot\sC(-,F(a')) 
\end{align*}
For objects 
$c,c'$ of $\sC$, the corresponding  evaluation 
is induced by the composition of morphisms as in the following diagram.
\[\xymatrix{ 
  \coprod_{a\in \mc{A}} \sC(c,F(a))\otimes \sC(F(a),c') \ar[r]\ar[d]
  &\sC(c,c')
  \\
  \sC(c,F(-))\odot \sC(F(-),c') \ar@{.>}[ur]
}\]

If $\mc{Q}$ is an $(\mc{C},\mc{C})$-bimodule and $F$ is as above, we have the following composite 
\[
  \rbm{\epsilon}{F}{\mc{C}}{\mc{Q}}\colon {_F\mc{Q}_F}\odot {_F\mc{C}}
  \cong {_F\mc{C}}\odot \mc{Q}\odot \mc{C}_F\odot {_F\mc{C}} 
  \xrightarrow{\rsm{\epsilon}{_F\mc{C}}{\mc{C}_F}{\mc{Q}}}{_F\mc{C}}\odot \mc{Q} 
\]
and the corresponding maps for $\rbm{\eta}{F}{\mc{C}}{\mc{Q}}$, $\lbm{\epsilon}{F}{\mc{C}}{\mc{Q}}$, and $\lbm{\eta}{F}{\mc{C}}{\mc{Q}}$.

In later examples the map $\phi$ in \cref{base_change_one_object} is a composite 
\begin{equation}
 \mc{Q}\odot \mc{M}\xrightarrow{\psi \odot  \id_\mc{M}}\mc{M}\odot  \mc{P}\odot \mc{N} \odot \mc{M}\xrightarrow{\rsm{\epsilon}{\mc{M}}{\mc{N}}{\mc{P}}} \mc{M}\odot \mc{P}
\end{equation}
for a map $\psi\colon  \mc{Q}\to \mc{M}\odot \mc{P} \odot \mc{N}$.

Then  \cref{prop:tightening} implies the trace of \eqref{switch_for_trace} is the composite 
$\shvar{}{\mc{Q}}\xrightarrow{\shvar{}{\psi}}\shvar{}{\mc{M}\odot \mc{P} \odot \mc{N}}\xrightarrow{\mathrm{tr}\left(\rsm{\epsilon}{\mc{M}}{\mc{N}}{\mc{P}}\right)}\shvar{}{\mc{P}}$
and \eqref{eq:base_change_one_object} becomes
\begin{equation}
\xymatrix{
 \shvar{}{{_{E_c}\mc{Q}_{E_c}}}\ar[d]^{\mathrm{tr}\left(\rbm{\epsilon}{E_c}{\mc{C}}{\mc{Q}}\right)}
   \ar[rrr]^-{\mathrm{tr}\left({_{E_c}\mc{C}}\odot \phi\odot \mc{D}_{E_d}\right)}
 &&&\shvar{}{_{E_d}\mc{P}_{E_d}}\ar[d]^{\mathrm{tr}\left(\rbm{\epsilon}{E_d}{\mc{D}}{\mc{P}}\right)}
 \\
 \shvar{}{\mc{Q}}\ar[r]^-{\shvar{}{\psi}}
 &\shvar{}{\mc{M}\odot \mc{P}\odot \mc{N}}\ar[rr]^-{\mathrm{tr}\left(\rsm{\epsilon}{\mc{M}}{\mc{N}}{\mc{P}}\right )} 
 &&\shvar{}{\mc{P}}
 }
\end{equation}

For algebras $A$ and $C$, a commuting diagram of maps of algebra
\[\xymatrix{A\ar[r]^j\ar[d]^f&A\ar[d]^f\\C\ar[r]^k&C}\]
defines a commuting diagram of functors
\[\xymatrix{
\Mod_C^c\ar[d]_-{-\sma_C C_f}\ar[r]^-{-\sma_C C_k}&\Mod_C^c\ar[d]^-{-\sma_C C_f}
\\
\Mod_A^c\ar[r]^-{-\sma_A A_j}&\Mod_A^c}
\] and 
 induces maps 
\begin{gather} C_k\odot C_f\to C_f\odot A_j.
\\

(\Mod_C^c)_{-\wedge_CC_k}\odot {_{-\wedge_CC_f}(\Mod_A^c)}\to 
{_{-\wedge_CC_f}(\Mod_A^c)}\odot (\Mod_A^c)_{-\wedge_AA_j}
\end{gather}

Let $A$ be a ring spectrum, and let $f\colon  P \to P$ be an endomorphism of an $A$-module $P$. Then $f$ determines an element of $\pi_0 (\operatorname{THH}(\operatorname{Mod}^c_A))$ as follows. First, it determines a map of modules $S \to \operatorname{End}(P) $ adjoint to $f$. This includes into the zero skeleton of $\thh(\operatorname{Mod}^c_A)$, which is
\[
\operatorname{sk}^0 (\thh(\operatorname{Mod}^c_A)) = \bigvee_{M \in \operatorname{Mod}^c_A} \operatorname{End}(M) = \bigvee_{M \in \operatorname{Mod}^c_A} \operatorname{Mod}^c_A (M, M). 
\]
The zero skeleton includes into $\operatorname{THH}(\operatorname{Mod}^c_A)$. Thus, we have a composite
\begin{equation*}
S \to \operatorname{End}_{\Mod^c_A}(P) \hookrightarrow \bigvee_{M \in\operatorname{Mod}^c_A} \operatorname{Mod}^c_A (M, M) \hookrightarrow \thh(\operatorname{Mod}^c_A)
\end{equation*}
Finally, Morita invariance extends this map to
\begin{equation}
S \to \operatorname{End}_{\Mod^c_A}(P) \hookrightarrow \bigvee_{M \in\operatorname{Mod}^c_A} \operatorname{Mod}^c_A (M, M) \hookrightarrow \thh(\operatorname{Mod}^c_A) \xrightarrow{\sim} \thh(A)
\end{equation}
yielding a map $S \to \operatorname{THH}(A)$, i.e. an element of $\pi_0 \operatorname{THH}(A)$.

As in \cref{lem:base_change_euler_ex}, 
the following diagrams commute. 
\begin{equation}
\xymatrix{
\coprod_{c} \mc{C}(I(c),I(c))\ar@{=}[r]
&\coprod_{c} \mc{C}(c,c)\ar[d]
\\
\shvar{}{{_I(U_\mc{C})_I}}\ar[r]^-{\mathrm{tr}\left(\rbm{\epsilon}{I}{\mc{C}}{U_\mc{C}}\right)}\ar@{=}[u]
&\shvar{}{\mc{C}}
}\quad \text{and}\quad \xymatrix{
 \mc{C}(I_c(\ast),I_c(\ast))\ar[r]
&\coprod_{c} \mc{C}(c,c)\ar[d]
\\
\shvar{}{{_{I_c}(U_\mc{C})_{I_c}}}\ar[r]^-{\mathrm{tr}\left(\rbm{\epsilon}{I_c}{\mc{C}}{U_\mc{C}}\right)}\ar@{=}[u]
&\shvar{}{\mc{C}}
}\end{equation}

The $\Delta^n$ are assembled into a cosimplicial space $\Delta^\bullet$ via the cosimplicial maps
\begin{align*}
d_i (u_0, \dots, u_n) &= (u_0, \dots, u_i + u_{i+1}, \dots, u_n)\\
s_i (u_0, \dots, u_n) &= (u_0, \dots, u_i, 0, u_{i+1}, \dots, u_n) 
\end{align*}
